/**
 * The `zotero_export` tool: turn item refs into citations or formatted
 * exports. Citation mode pairs every requested ref with Zotero's own HTML
 * citation, ordered as requested; bibliography mode yields the joined
 * CSL-sorted bibliography. BibTeX, BibLaTeX, RIS and CSV pass Zotero's batch
 * body through; CSL JSON combines the requested items' translator records.
 * Per-item entries carry their refs and export keys where available.
 * Export output is never mid-truncated:
 * it either fits the provider's character limit or fails with a typed error.
 * @module dsh-zotero/tools/export
 */

import { identityToolWrapper, type ToolWrapper } from '../result-delivery.js'
import type {} from '@deepseek-ai/dsh-tool-present/types'
import type {} from '@deepseek-ai/dsh-fs'
import type {} from '@deepseek-ai/dsh-sandbox'
import type {} from '@deepseek-ai/dsh-working-directory'

import type { Context } from '@deepseek-ai/cordis'
import type { ContentBlock } from '@deepseek-ai/dsh-llm'
import {
  ToolContextUnavailableError,
  type InferArgs,
  type InferValue,
  type ToolResult,
  type ToolResultView,
} from '@deepseek-ai/dsh-tools'
import { defineZoteroTool as defineTool } from '../define-tool.js'
import type { ResolvedConfig } from '../config.js'
import { invalidArgs } from '../errors.js'
import { parseSupportedRef } from '../refs.js'
import { formatCitationKeyConflict } from '../citation-key.js'
import { assertExportRefsWithinCap, assertUniqueExportRefs } from '../export-limits.js'
import { boundedPresentationMeta, projectExportMeta } from '../presentation-meta.js'
import { metaRecordOf } from './present.js'
import {
  ZOTERO_EXPORT_FORMATS,
  ZOTERO_ITEMKEY_BATCH,
  ZOTERO_ITEMIZED_EXPORT_FORMATS,
} from '../constants.js'
import { assertNonEmptyList, REF_ARG_HINT } from './validate.js'
import type { ZoteroService } from '../service.js'
import type { ZoteroExportFormat, ZoteroExportRequest } from '../types.js'
import {
  BACKGROUND_OUTPUT_PROPERTIES,
  PROMOTED_OUTPUT_PROPERTIES,
  RUN_IN_BACKGROUND_PARAMETER,
  executeWithJobs,
  isJobArm,
  jobPolicyOf,
  presentJobArm,
  renderJobArm,
} from '../job-runner.js'

const EXPORT_PARAMETERS = {
  refs: {
    type: 'array',
    items: { type: 'string' },
    required: true,
    description: `${REF_ARG_HINT} refs in output order; maxExportRefs applies. citation batches above ${ZOTERO_ITEMKEY_BATCH}; other formats require batching above that cap.`,
  },
  format: {
    type: 'string',
    enum: [...ZOTERO_EXPORT_FORMATS],
    required: true,
    description:
      'citation: per-ref HTML; bibliography: joined CSL; other formats: translator exports.',
  },
  style: {
    type: 'string',
    description: 'CSL style id for citation/bibliography (defaults to the configured style).',
  },
  locale: {
    type: 'string',
    description: 'CSL locale for citation/bibliography (defaults to the configured locale).',
  },
  outputFile: {
    type: 'string',
    description:
      'Optional session-workspace path for the exported bibliography, translator, or CSV text.',
  },
  ...RUN_IN_BACKGROUND_PARAMETER,
} as const

type ExportArgs = InferArgs<typeof EXPORT_PARAMETERS>

const EXPORT_ITEM_PROPERTIES = {
  ref: { type: 'string', required: true },
  exportKey: { type: 'string' },
  citationKey: { type: 'string' },
  citationKeySource: { type: 'string', enum: ['native', 'extra'] },
  citationKeyConflict: {
    type: 'object',
    additionalProperties: false,
    properties: {
      native: { type: 'string', required: true },
      extra: { type: 'string', required: true },
    },
  },
  title: { type: 'string' },
  entryIndex: { type: 'integer' },
} as const

const EXPORT_OUTPUT_SCHEMA = {
  oneOf: [
    {
      type: 'object',
      additionalProperties: false,
      properties: BACKGROUND_OUTPUT_PROPERTIES,
    },
    {
      type: 'object',
      additionalProperties: false,
      properties: PROMOTED_OUTPUT_PROPERTIES,
    },
    {
      type: 'object',
      additionalProperties: false,
      properties: {
        format: { type: 'string', const: 'citation', required: true },
        style: { type: 'string' },
        locale: { type: 'string' },
        citations: {
          type: 'array',
          required: true,
          items: {
            type: 'object',
            additionalProperties: false,
            properties: {
              ref: { type: 'string', required: true },
              text: { type: 'string', required: true },
            },
          },
        },
      },
    },
    {
      type: 'object',
      additionalProperties: false,
      properties: {
        format: { type: 'string', const: 'bibliography', required: true },
        style: { type: 'string' },
        locale: { type: 'string' },
        text: { type: 'string', required: true },
        outputFile: { type: 'string' },
      },
    },
    {
      type: 'object',
      additionalProperties: false,
      properties: {
        format: { type: 'string', const: 'csv', required: true },
        text: { type: 'string', required: true },
        outputFile: { type: 'string' },
      },
    },
    {
      type: 'object',
      additionalProperties: false,
      properties: {
        format: {
          type: 'string',
          enum: [...ZOTERO_ITEMIZED_EXPORT_FORMATS],
          required: true,
        },
        style: { type: 'string' },
        locale: { type: 'string' },
        text: { type: 'string', required: true },
        outputFile: { type: 'string' },
        items: {
          type: 'array',
          required: true,
          items: {
            oneOf: [
              { type: 'object', additionalProperties: false, properties: EXPORT_ITEM_PROPERTIES },
              {
                type: 'object',
                additionalProperties: false,
                properties: {
                  ...EXPORT_ITEM_PROPERTIES,
                  start: { type: 'integer', required: true },
                  end: { type: 'integer', required: true },
                },
              },
            ],
          },
        },
      },
    },
  ],
} as const

type ExportOutput = InferValue<typeof EXPORT_OUTPUT_SCHEMA>

/** The model-facing message for an empty refs list. */
export const EXPORT_REFS_EMPTY_MESSAGE = 'refs must list at least one zotero:// item ref'

// The shared cap message stays importable from the tool module: the tool spec
// asserts it by identity and the library endpoint refuses with the same text.
export { exportRefsOverCapMessage } from '../export-limits.js'

/** The model-facing messages for a blank style or locale argument. */
export const EXPORT_STYLE_BLANK_MESSAGE = 'style must be a non-empty CSL style id when provided'
export const EXPORT_LOCALE_BLANK_MESSAGE = 'locale must be a non-empty CSL locale when provided'

function buildRequest(args: ExportArgs, config: ResolvedConfig): ZoteroExportRequest {
  assertNonEmptyList(args.refs, EXPORT_REFS_EMPTY_MESSAGE)
  assertExportRefsWithinCap(args.refs.length, config.maxExportRefs, invalidArgs)
  const refs = args.refs.map((value) => {
    const ref = parseSupportedRef(value, ['item'])
    return ref
  })
  assertUniqueExportRefs(refs, invalidArgs)
  if (
    args.outputFile !== undefined &&
    (args.outputFile.trim() === '' || args.format === 'citation')
  )
    invalidArgs(
      'outputFile requires a non-empty path and a bibliography, translator, or CSV export',
    )
  const style = args.style?.trim()
  if (style === '') invalidArgs(EXPORT_STYLE_BLANK_MESSAGE)
  const locale = args.locale?.trim()
  if (locale === '') invalidArgs(EXPORT_LOCALE_BLANK_MESSAGE)
  return {
    refs,
    format: args.format as ZoteroExportFormat,
    ...(style !== undefined ? { style } : {}),
    ...(locale !== undefined ? { locale } : {}),
  }
}

function renderExport(_args: unknown, value: ExportOutput): ContentBlock[] {
  if (isJobArm(value)) return renderJobArm(value)
  if (value.format === 'citation') {
    return [
      {
        type: 'text',
        text: value.citations.map((entry) => `${entry.ref}: ${entry.text}`).join('\n'),
      },
    ]
  }
  // Preserve translator bytes, including whitespace and BOM.
  const text = value.text
  const outputFile = (value as { outputFile?: string }).outputFile
  const notes: string[] = []
  if (outputFile !== undefined) {
    notes.push(`Export written to ${outputFile}.`)
  }
  const mapped =
    'items' in value && Array.isArray(value.items)
      ? value.items.map((item) => {
          const identity = [
            `ref: ${item.ref}`,
            item.exportKey === undefined ? undefined : `exportKey: ${item.exportKey}`,
            item.citationKey === undefined ? undefined : `citationKey: ${item.citationKey}`,
            item.title,
            item.entryIndex === undefined ? undefined : `entryIndex: ${item.entryIndex}`,
            item.citationKeyConflict === undefined
              ? undefined
              : `citationKey conflict: ${formatCitationKeyConflict(item.citationKeyConflict)}`,
          ]
            .filter((part): part is string => part !== undefined)
            .join(' · ')
          const unavailable =
            item.exportKey === undefined && item.title === undefined
              ? ' (mapping unavailable; do not pair by raw order)'
              : ''
          return `- ${identity}${unavailable}`
        })
      : []
  const mapping = mapped.length > 0 ? `Mapped items:\n${mapped.join('\n')}` : ''
  const notesText = notes.length > 0 ? `(${notes.join(' ')})` : ''
  const auxiliary = [mapping, notesText].filter((part) => part !== '').join('\n\n')
  // The translator body stays its own block: the card reads it as the exact
  // artifact for copy and download, so the mapping and the notes can never
  // leak into it. The model still receives both blocks.
  return auxiliary === ''
    ? [{ type: 'text', text }]
    : [
        { type: 'text', text },
        { type: 'text', text: auxiliary },
      ]
}

/**
 * The completed export card: the exported citation count in citation mode,
 * else the requested ref count with the translator format. `meta` is absent
 * on nested code dispatch or malformed replay records, and a failed call
 * keeps the raw error content; both fall back to the generic card.
 */
function presentExportResult(_args: ExportArgs, result: ToolResult): ToolResultView | undefined {
  const record = metaRecordOf(result)
  if (record === undefined) return undefined
  const jobArm = presentJobArm('Zotero export', record)
  if (jobArm !== undefined) return jobArm
  if (typeof record.format !== 'string' || record.format === '') return undefined
  if (record.format === 'citation') {
    if (typeof record.count !== 'number') return undefined
    return { card: 'generic', title: `Zotero export: ${record.count} citations` }
  }
  if (typeof record.requested !== 'number') return undefined
  return { card: 'generic', title: `Zotero export: ${record.requested} refs as ${record.format}` }
}

/**
 * Register `zotero_export` for the plugin lifetime. Each call checks the
 * current background policy and job registry.
 * @param ctx - the plugin context.
 * @param service - the zotero service owning the request path.
 * @param wrap - the delivery envelope.
 */
export function registerExportTool(
  ctx: Context,
  service: ZoteroService,
  wrap: ToolWrapper = identityToolWrapper,
): () => void {
  const definition = wrap(
    defineTool({
      name: 'zotero_export',
      description: [
        'Export citations in requested ref order, a CSL-sorted bibliography, or translator text in Zotero order with ref-to-entry mappings.',
        'For exported files, declare the result using present.',
      ].join(' '),
      parameters: EXPORT_PARAMETERS,
      output: {
        schema: EXPORT_OUTPUT_SCHEMA,
        render: renderExport,
        // Drop optional document previews while retaining citation attribution.
        presentationMeta: (args, value) => {
          if (isJobArm(value)) return value
          return boundedPresentationMeta(
            projectExportMeta(value as Parameters<typeof projectExportMeta>[0], args.refs),
            ['items'],
          )
        },
      },
      presentCall: (args) => ({
        card: 'generic',
        title: 'Export Zotero citations',
        rawInput: `${args.refs.length} refs · ${args.format}`,
      }),
      presentResult: presentExportResult,
      isConcurrencySafe: (args) => args.outputFile === undefined,
      async execute(args, exec) {
        const exportArgs = args
        const request = buildRequest(exportArgs, service.config)
        const session = exec.agent?.session
        const fs = ctx.get('fs')
        const workingDirectory = ctx.get('workingDirectory')
        if (exportArgs.outputFile !== undefined && (!session || !fs || !workingDirectory)) {
          throw new ToolContextUnavailableError(
            'Export file delivery requires filesystem, working directory and session',
          )
        }
        if (
          exportArgs.outputFile !== undefined &&
          fs!.sandboxMode !== undefined &&
          !ctx.get('sandboxPolicy')
        )
          throw new ToolContextUnavailableError('Sandbox filesystem requires sandboxPolicy')
        const cwd =
          exportArgs.outputFile !== undefined
            ? await workingDirectory!.ensure(exec.agent!, exec.signal)
            : undefined
        return executeWithJobs({
          runner: service.jobRunner,
          exec,
          label: `zotero_export (${exportArgs.refs.length} refs, ${exportArgs.format})`,
          run: async (signal, onProgress) => {
            let result: Awaited<ReturnType<typeof service.export>> & {
              outputFile?: string
            } = await service.export(request, signal, onProgress)
            if (result.format === 'citation') return result
            signal.throwIfAborted()
            if (exportArgs.outputFile !== undefined) {
              const policyService = ctx.get('sandboxPolicy')
              if (fs!.sandboxMode !== undefined && !policyService)
                throw new ToolContextUnavailableError('Sandbox filesystem requires sandboxPolicy')
              const target = await fs!.resolve(exportArgs.outputFile.trim(), { cwd, signal })
              signal.throwIfAborted()
              const policy = policyService?.resolve({ session: session! })
              await fs!.writeText(target, result.text, undefined, signal, policy)
              const path = fs!.processPath(target)
              signal.throwIfAborted()
              result = { ...result, outputFile: path }
            }
            signal.throwIfAborted()
            return result
          },
          outputLimitBytes: service.config.maxInlineResultBytes,
          runInBackground: exportArgs.run_in_background === true,
          policy: jobPolicyOf(service.config),
        })
      },
    }),
  )
  return ctx.tools.register(definition)
}
